arde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais mariner le poisson 20 min dans le jus des citrons avec l'ail, sel et poivre.","timer":{"label":"Marinade","min":20}},{"text":"Fais fondre les oignons émincés dans l'huile 15 min avec la moutarde.","timer":{"label":"Cuisson","min":15}},{"text":"Pose le poisson sur les oignons, verse la marinade, couvre et cuis 12 min.","timer":{"label":"Cuisson","min":12}}]},{"title":"Cabillaud à la provençale","intro":"Un cabillaud ensoleillé, à la tomate, aux olives et au thym.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"cod provencal tomato olives","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"olive noire","plural":"olives noires","qty":50,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais revenir l'oignon et l'ail dans l'huile, ajoute les tomates, les olives et le thym. Cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Verse dans un plat, pose le cabillaud dessus, sale et poivre.","time